import sqlite3
con=sqlite3.connect("file:db/snapshots/v0.sqlite?mode=ro",uri=True)
def q(s): return con.execute(s).fetchall()
print("status sets:",q("select status_code,count(*) from fact_orders group by 1"),q("select status_code,count(*) from fact_costs group by 1"),q("select status_code,count(*) from fact_tickets group by 1"))
print("amount min per tbl:",q("select (select round(min(amount),2) from fact_orders),(select round(min(amount),2) from fact_costs),(select round(min(net_amount),2) from fact_returns),(select round(min(gross_amount),2) from fact_budget)"))
print("negcount:",q("select (select count(*) from fact_orders where amount<0),(select count(*) from fact_costs where amount<0)"))
print("agg all tables sample:")
for t in ["agg_daily_sales","agg_monthly_gmv","agg_region_share","agg_funnel","agg_forecast_error","agg_sla_summary","agg_cost_breakdown","agg_inventory_turnover","agg_customer_ltv","agg_cohort_retention","agg_channel_mix","agg_product_rank"]:
    print(" ",t,q(f"select round(min(metric_value),4),round(max(metric_value),4),round(min(metric_ratio),4),round(max(metric_ratio),4),count(distinct version_tag),count(distinct source_table),sum(is_partial) from {t}"))
print("agg version/source:",q("select version_tag,source_table,count(*) from agg_daily_sales group by 1,2"))
print("log types:",q("select event_type,count(*) from log_query_audit group by 1"),q("select status,count(*) from log_query_audit group by 1"))
print("log actor:",q("select count(distinct actor),min(actor) from log_query_audit"))
print("log dur:",q("select round(min(duration_ms),2),round(max(duration_ms),2) from log_query_audit"))
print("log err:",q("select error_code,count(*) from log_query_audit group by 1 limit 6"))
print("fact dates 2024-04:",q("select count(*) from fact_orders where date_key between 20240401 and 20240430"))
print("status x month:",q("select status_code,count(*) from fact_orders where date_key between 20240401 and 20240430 group by 1"))
print("currency x month:",q("select currency_code,count(*) from fact_orders where date_key between 20240401 and 20240430 group by 1"))
print("unit price range:",q("select round(min(unit_price),2),round(max(unit_price),2) from fact_orders"))
print("dim_date cat by month:",q("select date_key/100, category, count(*) from dim_date where date_key between 20240101 and 20240514 group by 1,2"))
